    /** The harness page's elements, declared the way every page's Elements enum is. */
    enum Harness implements PageElement {
        ADD_BUTTON(page -> page.locator("css=#add")),
        HIDDEN_BUTTON(page -> page.locator("css=#hidden")),
        LATER_BUTTON(page -> page.locator("css=#later")),
        TWIN_BUTTON(page -> page.locator("css=.twin")),
        BROKEN_LOCATOR(page -> page.locator("xpath=//button[")),
        COUNT(page -> page.locator("css=#count")),
        SPACED_TEXT(page -> page.locator("css=#spaced")),
        NAME_FIELD(page -> page.locator("css=#name")),
        TOWN_FIELD(page -> page.locator("css=#town")),
        AGREE_BOX(page -> page.locator("css=#agree")),
        COLOUR_LIST(page -> page.locator("css=#colour")),
        LATE_TEXT(page -> page.locator("css=#late")),
        OFF_BUTTON(page -> page.locator("css=#off")),
        HELP_LINK(page -> page.locator("css=#help")),
        FAR_BUTTON(page -> page.locator("css=#far")),
        FAR_TEXT(page -> page.locator("css=#far-clicked")),
        REVEALED_HEADING(page -> page.locator("css=#reveal")),
        CONTACT_HEADING(page -> Headings.named(page, "Contact Us")),
        MISSING_HEADING(page -> Headings.named(page, "Nowhere"));

        private final LocatorProvider provider;

        Harness(LocatorProvider provider) {
            this.provider = provider;
        }

        @Override
        public Locator locator(Page page) {
            return provider.get(page);
        }
    }

    @BeforeEach
    void openTheHarnessPage() {
        // The page's one image fails at once, every time, without the network: network.txt must list it.
        context.route("**/harness-missing.png", route -> route.abort());
        page.setContent(PAGE);
        WaitActions.shortenWaits(500L);
    }

    @AfterEach
    void normalWaits() {
        WaitActions.shortenWaits(null);
    }

    // ---- evidence ------------------------------------------------------------------------------

    @Test
    @DisplayName("A failure leaves its evidence: screenshot, page, trace, steps, console, network, run")
    void aFailureLeavesItsEvidence() throws IOException {
        UserActions.click(page, Harness.ADD_BUTTON);
        AssertionError failure = failureOf(() -> Checks.isShown(page, Harness.HIDDEN_BUTTON));
        Path dir = evidence.failed(failure, browser().version(), true); // in full, however many failures the run had
        try {
            for (String file : List.of("screenshot.png", "page.html", "trace.zip", "steps.txt", "console.txt", "network.txt", "run.txt")) {
                Path path = dir.resolve(file);
                assertTrue(Files.isRegularFile(path) && Files.size(path) > 0, "A failure should leave " + path + ", and it is missing or empty.");
            }
            String steps = read(dir.resolve("steps.txt"));
            assertTrue(steps.contains("1. Click the add button\n2. Check that the hidden button is shown   <- FAILED HERE"),
                    "steps.txt should list the steps and mark the failed one; it says:\n" + steps);
            assertTrue(steps.contains("Because: java.lang.AssertionError: Expected the hidden button to be shown"),
                    "steps.txt should say why it failed; it says:\n" + steps);
            assertTrue(read(dir.resolve("page.html")).contains("<h1>Harness <span>page</span></h1>"),
                    "page.html should hold the page as it was when the test failed.");
            assertTrue(read(dir.resolve("console.txt")).contains("harness: a console error"),
                    "console.txt should hold the page's console errors; it says:\n" + read(dir.resolve("console.txt")));
            assertTrue(read(dir.resolve("network.txt")).contains("harness-missing.png"),
                    "network.txt should hold the request that failed; it says:\n" + read(dir.resolve("network.txt")));
            String explained = StepLog.failure(failure);
            assertTrue(explained.startsWith("   FAILED at step 2: Check that the hidden button is shown\n   because: Expected the hidden button to be shown"),
                    "A failure should be explained with its step and reason; it was:\n" + explained);
        } finally {
            Evidence.deleteAll(dir); // this failure was on purpose: it leaves nothing to be mistaken for a real one
        }
    }

