    @Test
    @DisplayName("assume skips, saying why, when what a test needs is not there; passes on when it is")
    void assumeSkipsSayingWhy() {
        Checks.assume(true, "never said");
        assertTrue(StepLog.steps().stream().noneMatch(step -> step.contains("never said")), "assume, met, should say nothing");
        try {
            Checks.assume(false, "no policy with an amount due in policies.csv");
            throw new AssertionError("assume, not met, should have skipped the test");
        } catch (Checks.NotMet skipped) {
            assertTrue("no policy with an amount due in policies.csv".equals(skipped.getMessage()), "The skip should say why; it said: " + skipped.getMessage());
        }
        List<String> steps = StepLog.steps();
        assertTrue(steps.get(steps.size() - 1).equals("Skipped: no policy with an amount due in policies.csv"), "The last step should say it was skipped, and why: " + steps);
    }

