    @Test
    @DisplayName("A locator that is not valid, or that matches several elements, is said to be so at once, not \"not shown\"")
    void locatorDefectsAreSaid() {
        // Two matches where one is meant (Playwright's strict mode): by a check, a reader and an action alike.
        String twins = "the twin button matches 2 elements on the page; its locator must match one (add .first(), or narrow it: ai/recipes/add-an-element.md)";
        says(() -> Checks.isShown(page, Harness.TWIN_BUTTON), twins);
        says(() -> Checks.hasText(page, Harness.TWIN_BUTTON, "Twin"), twins);
        says(() -> UserActions.click(page, Harness.TWIN_BUTTON), twins);
        says(() -> UserActions.type(page, Harness.TWIN_BUTTON, "x"), twins);
        // A locator that is not valid (the browser's own words follow, and differ by browser).
        saysAtFirst(() -> Checks.isShown(page, Harness.BROKEN_LOCATOR), "the broken locator's locator is not valid: ");
        saysAtFirst(() -> Checks.hasText(page, Harness.BROKEN_LOCATOR, "x"), "the broken locator's locator is not valid: ");
        saysAtFirst(() -> UserActions.click(page, Harness.BROKEN_LOCATOR), "the broken locator's locator is not valid: ");
        saysAtFirst(() -> UserActions.type(page, Harness.BROKEN_LOCATOR, "x"), "the broken locator's locator is not valid: ");
    }

