    @Test
    @DisplayName("Actions do what their steps say, and the steps say it")
    void actionsDoWhatTheySay() {
        UserActions.click(page, Harness.ADD_BUTTON);
        UserActions.click(page, Harness.ADD_BUTTON);
        Checks.hasText(page, Harness.COUNT, "2");
        UserActions.type(page, Harness.NAME_FIELD, "Ann");
        Checks.hasValue(page, Harness.NAME_FIELD, "Ann");
        UserActions.clear(page, Harness.NAME_FIELD);
        Checks.hasValue(page, Harness.NAME_FIELD, "");
        UserActions.typeSecret(page, Harness.NAME_FIELD, "hunter2");
        UserActions.tick(page, Harness.AGREE_BOX);
        assertTrue(Harness.AGREE_BOX.locator(page).isChecked(), "tick should tick the box.");
        UserActions.untick(page, Harness.AGREE_BOX);
        assertTrue(!Harness.AGREE_BOX.locator(page).isChecked(), "untick should untick the box.");
        UserActions.choose(page, Harness.COLOUR_LIST, "Blue");
        Checks.hasValue(page, Harness.COLOUR_LIST, "Blue");
        String read = UserActions.readText(page, Harness.SPACED_TEXT);
        assertTrue("Hello world".equals(read), "readText should read \"Hello world\"; it read \"" + read + "\".");
        List<String> expected = List.of(
                "Click the add button",
                "Click the add button",
                "Check that the count says \"2\"",
                "Type \"Ann\" into the name field",
                "Check that the name field holds \"Ann\"",
                "Clear the name field",
                "Check that the name field holds \"\"",
                "Type the secret into the name field",
                "Tick the agree box",
                "Untick the agree box",
                "Choose \"Blue\" in the colour list",
                "Check that the colour list holds \"Blue\"",
                "Read the spaced text: \"Hello world\"");
        assertTrue(StepLog.steps().equals(expected), "The step log should read, in order:\n" + expected + "\nIt read:\n" + StepLog.steps());
        assertTrue(StepLog.steps().stream().noneMatch(step -> step.contains("hunter2")), "A secret must never be logged.");
    }

    // ---- helpers ---------------------------------------------------------------------------------

    /** The check's failure: that it failed, and exactly what it said. */
    private static void saysAtFirst(Runnable check, String start) {
        AssertionError failure = failureOf(check);
        assertTrue(String.valueOf(failure.getMessage()).startsWith(start), "The failure should start:\n  " + start + "\nIt said:\n  " + failure.getMessage());
    }

    private static void says(Runnable check, String message) {
        AssertionError failure = failureOf(check);
        assertTrue(message.equals(failure.getMessage()), "The failure should say:\n  " + message + "\nIt said:\n  " + failure.getMessage());
    }

    private static AssertionError failureOf(Runnable check) {
        try {
            check.run();
        } catch (AssertionError failure) {
            return failure;
        }
        throw new AssertionError("The check passed, and it should have failed.");
    }

    private static String read(Path file) throws IOException {
        return Files.readString(file, StandardCharsets.UTF_8);
    }
